#include "Alarm.h"
#include "Config.h"
void Alarm::begin(uint8_t buzzerPin,uint8_t ledPin){_buzzerPin=buzzerPin;_ledPin=ledPin;pinMode(_buzzerPin,OUTPUT);pinMode(_ledPin,OUTPUT);_detectionEnabled=Config::settings.alarmEnabled;_buzzerEnabled=Config::settings.buzzerEnabled;_ledEnabled=Config::settings.ledEnabled;_thresholdCm=Config::settings.alarmDistanceCm;applyOutputs(false,false);}
void Alarm::setDetectionEnabled(bool enabled){_detectionEnabled=enabled;Config::settings.alarmEnabled=enabled;if(!enabled)clear();}void Alarm::setBuzzerEnabled(bool enabled){_buzzerEnabled=enabled;Config::settings.buzzerEnabled=enabled;if(!enabled)digitalWrite(_buzzerPin,LOW);}void Alarm::setLedEnabled(bool enabled){_ledEnabled=enabled;Config::settings.ledEnabled=enabled;if(!enabled)digitalWrite(_ledPin,LOW);}void Alarm::setManualLed(bool on){_manualLed=on;}void Alarm::setThreshold(float thresholdCm){_thresholdCm=constrain(thresholdCm,5.0f,400.0f);}
AlarmTransition Alarm::process(float distanceCm,bool valid){AlarmTransition t;if(!_detectionEnabled||!valid){t.active=_active;return t;}if(!_active&&distanceCm<=_thresholdCm){_active=true;_lastAlarmStateChangeMs=millis();t.activated=true;}else if(_active&&distanceCm>(_thresholdCm+_hysteresisCm)){_active=false;_lastAlarmStateChangeMs=millis();t.cleared=true;}t.active=_active;return t;}
void Alarm::clear(){_active=false;_lastAlarmStateChangeMs=millis();applyOutputs(false,_manualLed&&_ledEnabled);}void Alarm::applyOutputs(bool buzzerOn,bool ledOn){digitalWrite(_buzzerPin,buzzerOn?HIGH:LOW);digitalWrite(_ledPin,ledOn?HIGH:LOW);}void Alarm::updateOutputs(){const uint32_t now=millis();bool buzzerOn=false;bool ledOn=_manualLed&&_ledEnabled;if(_active){if(_buzzerEnabled)buzzerOn=((now-_lastAlarmStateChangeMs)%700)<160;if(_ledEnabled)ledOn=((now-_lastAlarmStateChangeMs)%400)<200;}applyOutputs(buzzerOn,ledOn);}
